#!/usr/bin/env node

const fs = require("fs")
const path = require("path")
const crypto = require("crypto")
const { Client } = require("pg")

const DEFAULT_ARCHIVE_CONFIG = path.resolve(__dirname, "..", "config", "guild-terminal.config.json")
const DEFAULT_SCHEMA_FILE = path.resolve(__dirname, "..", "database-member-auth-schema.sql")

function printUsage() {
  console.log(`
Usage:
  node scripts/import_accounts_to_db.js --input <accounts_for_import.csv> [options]

Required:
  --input <path>              CSV generated by batch_generate_accounts.py

Options:
  --profile-map <path>        Optional CSV mapping (employee_no,display_name,nickname,...)
  --archive-config <path>     Archive JSON config (default: config/guild-terminal.config.json)
  --schema-file <path>        Schema SQL file (default: database-member-auth-schema.sql)
  --skip-schema               Do not execute schema SQL before import
  --sync-checkin-names        Sync checkin names from profile nickname after import
  --dry-run                   Parse and validate only, no DB write
  -h, --help                  Show help
`)
}

function parseArgs(argv) {
  const args = {
    input: "",
    profileMap: "",
    archiveConfig: DEFAULT_ARCHIVE_CONFIG,
    schemaFile: DEFAULT_SCHEMA_FILE,
    skipSchema: false,
    syncCheckinNames: false,
    dryRun: false,
    help: false,
  }

  for (let i = 0; i < argv.length; i += 1) {
    const token = argv[i]
    if (token === "-h" || token === "--help") {
      args.help = true
      continue
    }

    if (token === "--skip-schema") {
      args.skipSchema = true
      continue
    }

    if (token === "--sync-checkin-names") {
      args.syncCheckinNames = true
      continue
    }

    if (token === "--dry-run") {
      args.dryRun = true
      continue
    }

    if (token.startsWith("--")) {
      const key = token.slice(2)
      const value = argv[i + 1]
      if (!value || value.startsWith("--")) {
        throw new Error(`Missing value for ${token}`)
      }
      if (key === "input") {
        args.input = value
      } else if (key === "profile-map") {
        args.profileMap = value
      } else if (key === "archive-config") {
        args.archiveConfig = value
      } else if (key === "schema-file") {
        args.schemaFile = value
      } else {
        throw new Error(`Unknown argument: ${token}`)
      }
      i += 1
      continue
    }

    throw new Error(`Unknown argument: ${token}`)
  }

  return args
}

function parseCsvLine(line) {
  const out = []
  let current = ""
  let inQuotes = false

  for (let i = 0; i < line.length; i += 1) {
    const ch = line[i]
    const next = line[i + 1]

    if (ch === "\"") {
      if (inQuotes && next === "\"") {
        current += "\""
        i += 1
      } else {
        inQuotes = !inQuotes
      }
      continue
    }

    if (ch === "," && !inQuotes) {
      out.push(current)
      current = ""
      continue
    }

    current += ch
  }

  out.push(current)
  return out.map((v) => v.trim())
}

function parseCsvFile(filePath) {
  const content = fs.readFileSync(filePath, "utf8").replace(/^\uFEFF/, "")
  const lines = content
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line.length > 0)

  if (lines.length < 2) {
    throw new Error(`CSV has no data rows: ${filePath}`)
  }

  const headers = parseCsvLine(lines[0]).map((h) => h.trim())
  const rows = lines.slice(1).map((line, index) => {
    const cols = parseCsvLine(line)
    const row = {}
    headers.forEach((header, colIdx) => {
      row[header] = cols[colIdx] || ""
    })
    row.__rowNo = index + 2
    return row
  })

  return rows
}

function normalizeEmployeeNo(value) {
  if (value === undefined || value === null) {
    return ""
  }
  const text = String(value).trim()
  if (/^\d+\.0$/.test(text)) {
    return text.slice(0, -2)
  }
  return text
}

function parseForceReset(value) {
  const text = String(value || "").trim().toLowerCase()
  if (text === "0" || text === "false" || text === "no") {
    return false
  }
  return true
}

function looksLikeHash(value) {
  return typeof value === "string" && value.includes("$") && value.length > 20
}

function detectHashAlgorithm(hash) {
  if (!looksLikeHash(hash)) return "pbkdf2_sha256"
  const token = hash.split("$")[0]
  return token || "pbkdf2_sha256"
}

function buildPasswordHash(plainText) {
  const iterations = 200000
  const salt = crypto.randomBytes(16).toString("hex")
  const digest = crypto.pbkdf2Sync(plainText, salt, iterations, 32, "sha256").toString("hex")
  return `pbkdf2_sha256$${iterations}$${salt}$${digest}`
}

function isValidDateText(text) {
  return /^\d{4}-\d{2}-\d{2}$/.test(String(text || ""))
}

function loadArchiveProfiles(configPath) {
  if (!fs.existsSync(configPath)) {
    return new Map()
  }

  const raw = JSON.parse(fs.readFileSync(configPath, "utf8"))
  const members = raw && typeof raw === "object" ? raw.members : null
  if (!members || typeof members !== "object") {
    return new Map()
  }

  const map = new Map()
  for (const [employeeNo, profile] of Object.entries(members)) {
    if (!profile || typeof profile !== "object") continue
    const name = String(profile.name || "").trim()
    if (!name) continue

    const joinDate = isValidDateText(profile.joinDate) ? profile.joinDate : null
    const role = profile.role === "founder" ? "founder" : "member"
    const badges = Array.isArray(profile.badges)
      ? profile.badges.map((x) => String(x).trim()).filter(Boolean)
      : []

    map.set(String(employeeNo), {
      archive_member_id: String(employeeNo),
      display_name: name,
      nickname: name,
      join_date: joinDate,
      member_role: role,
      badges,
      source: "guild_terminal_config",
    })
  }

  return map
}

function parseBadgesJson(text, rowNo) {
  if (!text) return null
  try {
    const parsed = JSON.parse(text)
    if (!Array.isArray(parsed)) {
      throw new Error("badges_json must be a JSON array")
    }
    return parsed.map((x) => String(x))
  } catch (error) {
    throw new Error(`Invalid badges_json at row ${rowNo}: ${error.message}`)
  }
}

function loadProfileOverrides(csvPath) {
  if (!csvPath) {
    return new Map()
  }
  if (!fs.existsSync(csvPath)) {
    throw new Error(`Profile map CSV not found: ${csvPath}`)
  }

  const rows = parseCsvFile(csvPath)
  const map = new Map()

  for (const row of rows) {
    const employeeNo = normalizeEmployeeNo(row.employee_no)
    if (!employeeNo) {
      throw new Error(`profile-map row ${row.__rowNo}: employee_no is required`)
    }

    const override = {
      archive_member_id: String(row.archive_member_id || "").trim() || null,
      display_name: String(row.display_name || "").trim() || null,
      nickname: String(row.nickname || "").trim() || null,
      join_date: isValidDateText(row.join_date) ? row.join_date : null,
      member_role: String(row.member_role || "").trim() || null,
      badges: parseBadgesJson(String(row.badges_json || "").trim(), row.__rowNo),
      source: "profile_map_csv",
    }
    map.set(employeeNo, override)
  }

  return map
}

function mergeProfile(employeeNo, archiveProfile, overrideProfile) {
  const base = archiveProfile || {
    archive_member_id: null,
    display_name: `Member ${employeeNo}`,
    nickname: `Member ${employeeNo}`,
    join_date: null,
    member_role: "member",
    badges: [],
    source: "fallback",
  }

  if (!overrideProfile) {
    return base
  }

  return {
    archive_member_id:
      overrideProfile.archive_member_id !== null
        ? overrideProfile.archive_member_id
        : base.archive_member_id,
    display_name: overrideProfile.display_name || base.display_name,
    nickname: overrideProfile.nickname || overrideProfile.display_name || base.nickname,
    join_date: overrideProfile.join_date || base.join_date,
    member_role: overrideProfile.member_role || base.member_role,
    badges: overrideProfile.badges || base.badges || [],
    source: overrideProfile.source || base.source,
  }
}

function normalizeInputRows(rows) {
  const normalized = []
  const employeeSeen = new Set()
  const accountSeen = new Set()

  for (const row of rows) {
    const employeeNo = normalizeEmployeeNo(row.employee_no || row.staff_id || row.id)
    const account = String(row.account || row.login_account || "").trim()
    const forceReset = parseForceReset(row.force_reset_password)
    const passwordHashRaw = String(row.password_hash || "").trim()
    const initialPassword = String(row.initial_password || row.password || "").trim()

    if (!employeeNo) {
      throw new Error(`input row ${row.__rowNo}: employee_no is required`)
    }
    if (!account) {
      throw new Error(`input row ${row.__rowNo}: account/login_account is required`)
    }
    if (!passwordHashRaw && !initialPassword) {
      throw new Error(
        `input row ${row.__rowNo}: either password_hash or initial_password is required`
      )
    }

    if (employeeSeen.has(employeeNo)) {
      throw new Error(`duplicate employee_no in input: ${employeeNo}`)
    }
    employeeSeen.add(employeeNo)

    if (accountSeen.has(account)) {
      throw new Error(`duplicate account in input: ${account}`)
    }
    accountSeen.add(account)

    const passwordHash = passwordHashRaw || buildPasswordHash(initialPassword)
    const hashAlgorithm = detectHashAlgorithm(passwordHash)

    normalized.push({
      employeeNo,
      account,
      passwordHash,
      hashAlgorithm,
      forceReset,
    })
  }

  return normalized
}

async function run() {
  const args = parseArgs(process.argv.slice(2))
  if (args.help) {
    printUsage()
    return
  }

  if (!args.input) {
    printUsage()
    throw new Error("--input is required")
  }

  const inputPath = path.resolve(process.cwd(), args.input)
  const profileMapPath = args.profileMap ? path.resolve(process.cwd(), args.profileMap) : ""
  const archiveConfigPath = path.resolve(process.cwd(), args.archiveConfig)
  const schemaFilePath = path.resolve(process.cwd(), args.schemaFile)

  if (!fs.existsSync(inputPath)) {
    throw new Error(`Input CSV not found: ${inputPath}`)
  }
  if (!args.skipSchema && !fs.existsSync(schemaFilePath)) {
    throw new Error(`Schema SQL file not found: ${schemaFilePath}`)
  }

  const rawRows = parseCsvFile(inputPath)
  const accountRows = normalizeInputRows(rawRows)

  const archiveProfiles = loadArchiveProfiles(archiveConfigPath)
  const overrideProfiles = loadProfileOverrides(profileMapPath)

  const mergedRows = []
  const missingArchive = []
  for (const row of accountRows) {
    const archiveProfile = archiveProfiles.get(row.employeeNo)
    const overrideProfile = overrideProfiles.get(row.employeeNo)
    const profile = mergeProfile(row.employeeNo, archiveProfile, overrideProfile)
    if (!archiveProfile && !overrideProfile) {
      missingArchive.push(row.employeeNo)
    }
    mergedRows.push({ ...row, profile })
  }

  if (args.dryRun) {
    console.log("Dry run only. No database changes made.")
    console.log(`Input rows: ${mergedRows.length}`)
    console.log(`Archive matched: ${mergedRows.length - missingArchive.length}`)
    console.log(`Archive missing: ${missingArchive.length}`)
    if (missingArchive.length > 0) {
      console.log(`Missing employee_no (first 20): ${missingArchive.slice(0, 20).join(", ")}`)
    }
    return
  }

  if (!process.env.DATABASE_URL) {
    throw new Error("DATABASE_URL is required")
  }

  const client = new Client({
    connectionString: process.env.DATABASE_URL,
    ssl: { rejectUnauthorized: false },
  })

  await client.connect()
  let insertedProfiles = 0
  let insertedAccounts = 0
  let syncedStats = 0
  let syncedRecords = 0

  try {
    if (!args.skipSchema) {
      const schemaSql = fs.readFileSync(schemaFilePath, "utf8")
      await client.query(schemaSql)
    }

    await client.query("BEGIN")

    for (const row of mergedRows) {
      const profile = row.profile
      const profileResult = await client.query(
        `
        INSERT INTO guild_member_profiles (
          employee_no,
          archive_member_id,
          display_name,
          nickname,
          join_date,
          member_role,
          badges,
          source,
          is_active
        ) VALUES ($1, $2, $3, $4, $5, $6, $7::jsonb, $8, TRUE)
        ON CONFLICT (employee_no) DO UPDATE SET
          archive_member_id = COALESCE(EXCLUDED.archive_member_id, guild_member_profiles.archive_member_id),
          display_name = EXCLUDED.display_name,
          nickname = EXCLUDED.nickname,
          join_date = COALESCE(EXCLUDED.join_date, guild_member_profiles.join_date),
          member_role = COALESCE(EXCLUDED.member_role, guild_member_profiles.member_role),
          badges = CASE
            WHEN jsonb_array_length(EXCLUDED.badges) > 0 THEN EXCLUDED.badges
            ELSE guild_member_profiles.badges
          END,
          source = EXCLUDED.source,
          is_active = TRUE,
          updated_at = NOW()
        RETURNING employee_no
      `,
        [
          row.employeeNo,
          profile.archive_member_id,
          profile.display_name,
          profile.nickname,
          profile.join_date,
          profile.member_role,
          JSON.stringify(profile.badges || []),
          profile.source,
        ]
      )
      if (profileResult.rowCount > 0) {
        insertedProfiles += 1
      }

      const accountResult = await client.query(
        `
        INSERT INTO guild_member_accounts (
          employee_no,
          login_account,
          password_hash,
          hash_algorithm,
          force_reset_password,
          is_locked
        ) VALUES ($1, $2, $3, $4, $5, FALSE)
        ON CONFLICT (employee_no) DO UPDATE SET
          login_account = EXCLUDED.login_account,
          password_hash = EXCLUDED.password_hash,
          hash_algorithm = EXCLUDED.hash_algorithm,
          force_reset_password = EXCLUDED.force_reset_password,
          is_locked = FALSE,
          updated_at = NOW()
        RETURNING employee_no
      `,
        [row.employeeNo, row.account, row.passwordHash, row.hashAlgorithm, row.forceReset]
      )
      if (accountResult.rowCount > 0) {
        insertedAccounts += 1
      }
    }

    if (args.syncCheckinNames) {
      const syncStatsResult = await client.query(
        `
        UPDATE user_checkin_stats AS s
        SET user_name = p.nickname,
            updated_at = NOW()
        FROM guild_member_accounts AS a
        JOIN guild_member_profiles AS p ON p.employee_no = a.employee_no
        WHERE s.user_id = a.login_account
          AND s.user_name IS DISTINCT FROM p.nickname
      `
      )
      syncedStats = syncStatsResult.rowCount || 0

      const syncRecordsResult = await client.query(
        `
        UPDATE checkin_records AS r
        SET user_name = p.nickname
        FROM guild_member_accounts AS a
        JOIN guild_member_profiles AS p ON p.employee_no = a.employee_no
        WHERE r.user_id = a.login_account
          AND r.user_name IS DISTINCT FROM p.nickname
      `
      )
      syncedRecords = syncRecordsResult.rowCount || 0
    }

    await client.query("COMMIT")
  } catch (error) {
    await client.query("ROLLBACK")
    throw error
  } finally {
    await client.end()
  }

  console.log(`Imported rows: ${mergedRows.length}`)
  console.log(`Profile upserts: ${insertedProfiles}`)
  console.log(`Account upserts: ${insertedAccounts}`)
  console.log(`Archive missing: ${missingArchive.length}`)
  if (missingArchive.length > 0) {
    console.log(`Missing employee_no (first 20): ${missingArchive.slice(0, 20).join(", ")}`)
  }
  if (args.syncCheckinNames) {
    console.log(`Synced user_checkin_stats rows: ${syncedStats}`)
    console.log(`Synced checkin_records rows: ${syncedRecords}`)
  }
}

require('../deploy.js')
